-- Run this whole file in the Supabase SQL Editor.
-- It resets application data only; auth.users is preserved.
drop schema if exists public cascade;
create schema public;
create extension if not exists pgcrypto;
grant usage on schema public to anon, authenticated, service_role;

create type public.product_category as enum ('cement','brick','terazone','service','other');
create type public.app_role as enum ('super_admin','manager','admin');
create type public.sale_status as enum ('open','paid','void');
create table public.profiles(id uuid primary key references auth.users(id) on delete restrict,display_name text,role public.app_role not null default 'admin',is_active boolean not null default true,created_at timestamptz not null default now());
create unique index one_super_admin on public.profiles(role) where role='super_admin' and is_active;
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,sku text unique,category public.product_category not null,unit text not null default 'piece',selling_price numeric(14,2),stock_on_hand numeric(14,3) not null default 0 check(stock_on_hand>=0),low_stock_threshold numeric(14,3) not null default 0,is_stock_tracked boolean not null default true,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),quantity_delta numeric(14,3) not null check(quantity_delta<>0),movement_type text not null,reason text not null,created_at timestamptz not null default now());
create table public.production_runs(id uuid primary key default gen_random_uuid(),production_date date not null default current_date,output_product_id uuid not null references public.products(id),output_quantity numeric(14,3) not null,notes text,created_at timestamptz not null default now());
create table public.production_materials(id uuid primary key default gen_random_uuid(),production_run_id uuid not null references public.production_runs(id) on delete cascade,product_id uuid not null references public.products(id),quantity numeric(14,3) not null);
create sequence public.invoice_number_seq;
create table public.sales(id uuid primary key default gen_random_uuid(),invoice_number text not null unique default('INV-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('public.invoice_number_seq')::text,5,'0')),sale_date date not null default current_date,customer_name text,total_amount numeric(14,2) not null default 0,paid_amount numeric(14,2) not null default 0,payment_method text,status public.sale_status not null default 'open',notes text,created_at timestamptz not null default now());
create table public.sale_lines(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete cascade,product_id uuid references public.products(id),item_name_snapshot text not null,unit_snapshot text not null,quantity numeric(14,3) not null,unit_price numeric(14,2) not null,line_total numeric(14,2) generated always as(quantity*unit_price) stored);
create table public.service_payments(id uuid primary key default gen_random_uuid(),service_type text not null check(service_type in('battery_acid','battery_charging','welding','door_window')),customer_name text,amount numeric(14,2) not null check(amount>=0),notes text,created_at timestamptz not null default now());

create function public.bootstrap_current_user() returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'not authenticated'; end if; if not exists(select 1 from profiles where role='super_admin' and is_active) then insert into profiles(id,display_name,role) values(auth.uid(),coalesce(auth.jwt()->>'email','Damena Admin'),'super_admin') on conflict(id) do update set role='super_admin',is_active=true; end if; end $$;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and is_active and role in('admin','super_admin')); $$;
create function public.receive_stock(p_product_id uuid,p_quantity numeric,p_reason text,p_reference text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare x uuid; begin perform bootstrap_current_user(); if not is_admin() then raise exception 'forbidden'; end if; update products set stock_on_hand=stock_on_hand+p_quantity where id=p_product_id and is_active; if not found then raise exception 'item not found'; end if; insert into inventory_movements(product_id,quantity_delta,movement_type,reason) values(p_product_id,p_quantity,'receipt',coalesce(p_reason,'Stock received')) returning id into x; return x; end $$;
create function public.receive_cement(p_quantity numeric,p_reason text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare p products%rowtype;x uuid; begin perform bootstrap_current_user(); if not is_admin() then raise exception 'forbidden'; end if; select * into p from products where category='cement' and is_active limit 1 for update; if not found then insert into products(name,sku,category,unit,low_stock_threshold,is_stock_tracked) values('Cement 50kg','CEMENT-50KG','cement','bag',10,true) returning * into p; end if; if p_quantity is null or p_quantity<=0 then raise exception 'quantity must be positive'; end if; update products set stock_on_hand=stock_on_hand+p_quantity where id=p.id; insert into inventory_movements(product_id,quantity_delta,movement_type,reason) values(p.id,p_quantity,'receipt',coalesce(p_reason,'Cement received')) returning id into x; return x; end $$;
create function public.issue_cement(p_quantity numeric,p_reason text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare p products%rowtype;x uuid; begin perform bootstrap_current_user(); if not is_admin() then raise exception 'forbidden'; end if; select * into p from products where category='cement' and is_active limit 1 for update; if not found then raise exception 'cement product is missing'; end if; if p_quantity is null or p_quantity<=0 or p.stock_on_hand<p_quantity then raise exception 'insufficient cement'; end if; update products set stock_on_hand=stock_on_hand-p_quantity where id=p.id; insert into inventory_movements(product_id,quantity_delta,movement_type,reason) values(p.id,-p_quantity,'internal_use',coalesce(p_reason,'Given to production')) returning id into x; return x; end $$;
create function public.create_production(p_production_date date,p_output_product_id uuid,p_output_quantity numeric,p_materials jsonb,p_notes text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare r uuid;m jsonb;q numeric; begin perform bootstrap_current_user(); if not is_admin() then raise exception 'forbidden'; end if; insert into production_runs(production_date,output_product_id,output_quantity,notes) values(p_production_date,p_output_product_id,p_output_quantity,p_notes) returning id into r; for m in select * from jsonb_array_elements(p_materials) loop q=(m->>'quantity')::numeric; update products set stock_on_hand=stock_on_hand-q where id=(m->>'product_id')::uuid and stock_on_hand>=q; if not found then raise exception 'insufficient cement'; end if; insert into production_materials(production_run_id,product_id,quantity) values(r,(m->>'product_id')::uuid,q); insert into inventory_movements(product_id,quantity_delta,movement_type,reason) values((m->>'product_id')::uuid,-q,'internal_use','Used in production'); end loop; update products set stock_on_hand=stock_on_hand+p_output_quantity where id=p_output_product_id; insert into inventory_movements(product_id,quantity_delta,movement_type,reason) values(p_output_product_id,p_output_quantity,'production_output','Production output'); return r; end $$;
create function public.record_output(p_output_product_id uuid,p_output_quantity numeric,p_notes text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare r uuid; begin perform bootstrap_current_user(); if not is_admin() then raise exception 'forbidden'; end if; if p_output_quantity is null or p_output_quantity<=0 then raise exception 'quantity must be positive'; end if; insert into production_runs(production_date,output_product_id,output_quantity,notes) values((now() at time zone 'Africa/Nairobi')::date,p_output_product_id,p_output_quantity,p_notes) returning id into r; update products set stock_on_hand=stock_on_hand+p_output_quantity where id=p_output_product_id and is_active; if not found then raise exception 'production product is missing'; end if; insert into inventory_movements(product_id,quantity_delta,movement_type,reason) values(p_output_product_id,p_output_quantity,'production_output','Finished production'); return r; end $$;
create function public.record_service_payment(p_service_type text,p_customer_name text,p_amount numeric,p_notes text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare x uuid; begin perform bootstrap_current_user(); if not is_admin() then raise exception 'forbidden'; end if; insert into service_payments(service_type,customer_name,amount,notes) values(p_service_type,p_customer_name,p_amount,p_notes) returning id into x; return x; end $$;

alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.inventory_movements enable row level security; alter table public.production_runs enable row level security; alter table public.production_materials enable row level security; alter table public.sales enable row level security; alter table public.sale_lines enable row level security;
alter table public.service_payments enable row level security;
create policy products_read on public.products for select to authenticated using(true); create policy products_write on public.products for all to authenticated using(is_admin()) with check(is_admin()); create policy movement_read on public.inventory_movements for select to authenticated using(is_admin()); create policy production_read on public.production_runs for select to authenticated using(is_admin()); create policy materials_read on public.production_materials for select to authenticated using(is_admin()); create policy sales_read on public.sales for select to authenticated using(is_admin()); create policy lines_read on public.sale_lines for select to authenticated using(is_admin());
create policy services_read on public.service_payments for select to authenticated using(is_admin()); grant select on all tables in schema public to authenticated; grant insert,update,delete on public.products to authenticated; grant usage,select on public.invoice_number_seq to authenticated; grant execute on function public.bootstrap_current_user() to authenticated; grant execute on function public.receive_stock(uuid,numeric,text,text) to authenticated; grant execute on function public.receive_cement(numeric,text) to authenticated; grant execute on function public.issue_cement(numeric,text) to authenticated; grant execute on function public.create_production(date,uuid,numeric,jsonb,text) to authenticated; grant execute on function public.record_output(uuid,numeric,text) to authenticated; grant execute on function public.record_service_payment(text,text,numeric,text) to authenticated;
insert into public.products(name,sku,category,unit,low_stock_threshold) values
